create or replace function partner.create_partner(
  p_tenant_id uuid,
  p_actor_id uuid,
  p_partner_type text,
  p_roles text[],
  p_person_profile jsonb default null,
  p_organization_profile jsonb default null,
  p_organization_primary_contact jsonb default null,
  p_confirm_duplicate boolean default false
)
returns table (
  partner_id uuid,
  warnings jsonb
)
language plpgsql
security definer
set search_path = partner, iam, pg_temp
as $$
declare
  v_partner_id uuid := gen_random_uuid();
  v_partner_type partner.partner_type;
  v_roles partner.partner_role_type[];
  v_display_name text;
  v_warnings jsonb := '[]'::jsonb;
  v_phone text;
  v_email text;
  v_tax_code text;
  v_name text;
  v_contact_person_id uuid;
  v_contact_display_name text;
  v_contact_phone text;
begin
  perform partner._assert_actor(p_actor_id);

  if not iam.has_permission(p_tenant_id, 'partner.create') then
    raise exception 'permission denied: partner.create';
  end if;

  begin
    v_partner_type := p_partner_type::partner.partner_type;
  exception
    when invalid_text_representation then
      perform partner._raise_partner_error('VALIDATION_ERROR', 'invalid partner_type');
  end;

  v_roles := partner._validate_roles(p_roles);

  if p_organization_primary_contact is not null
    and v_partner_type <> 'organization' then
    perform partner._raise_partner_error(
      'VALIDATION_ERROR',
      'organization_primary_contact requires organization partner'
    );
  end if;

  if v_partner_type = 'person' then
    if p_person_profile is null then
      perform partner._raise_partner_error('VALIDATION_ERROR', 'person_profile required');
    end if;
    v_display_name := btrim(coalesce(p_person_profile ->> 'full_name', ''));
    v_phone := p_person_profile ->> 'phone';
    v_email := p_person_profile ->> 'email';
    v_tax_code := p_person_profile ->> 'tax_code';
    v_name := p_person_profile ->> 'full_name';
  else
    if p_organization_profile is null then
      perform partner._raise_partner_error(
        'VALIDATION_ERROR',
        'organization_profile required'
      );
    end if;
    v_display_name := btrim(coalesce(p_organization_profile ->> 'organization_name', ''));
    v_phone := p_organization_profile ->> 'phone';
    v_email := p_organization_profile ->> 'email';
    v_tax_code := p_organization_profile ->> 'tax_code';
    v_name := p_organization_profile ->> 'organization_name';
  end if;

  if length(v_display_name) = 0 then
    perform partner._raise_partner_error('VALIDATION_ERROR', 'display_name is required');
  end if;

  v_warnings := partner._guard_duplicates(
    p_tenant_id,
    v_phone,
    v_email,
    v_tax_code,
    v_name,
    null,
    p_confirm_duplicate
  );

  insert into partner.partners (
    partner_id,
    tenant_id,
    partner_type,
    status,
    display_name,
    version,
    created_by,
    updated_by
  )
  values (
    v_partner_id,
    p_tenant_id,
    v_partner_type,
    'active',
    v_display_name,
    1,
    p_actor_id,
    p_actor_id
  );

  if v_partner_type = 'person' then
    perform partner._insert_person_profile(p_tenant_id, v_partner_id, p_person_profile);
  else
    perform partner._insert_organization_profile(
      p_tenant_id,
      v_partner_id,
      p_organization_profile
    );

    if p_organization_primary_contact is not null then
      v_contact_display_name := btrim(
        coalesce(p_organization_primary_contact ->> 'full_name', '')
      );
      v_contact_phone := btrim(
        coalesce(p_organization_primary_contact ->> 'phone', '')
      );

      if length(v_contact_display_name) = 0 then
        perform partner._raise_partner_error(
          'VALIDATION_ERROR',
          'primary contact full_name is required'
        );
      end if;
      if length(v_contact_phone) = 0 then
        perform partner._raise_partner_error(
          'VALIDATION_ERROR',
          'primary contact phone is required'
        );
      end if;

      v_warnings := v_warnings || partner._guard_duplicates(
        p_tenant_id,
        v_contact_phone,
        p_organization_primary_contact ->> 'email',
        null,
        null,
        v_partner_id,
        p_confirm_duplicate
      );

      v_contact_person_id := gen_random_uuid();
      insert into partner.partners (
        partner_id,
        tenant_id,
        partner_type,
        status,
        display_name,
        version,
        created_by,
        updated_by
      )
      values (
        v_contact_person_id,
        p_tenant_id,
        'person',
        'active',
        v_contact_display_name,
        1,
        p_actor_id,
        p_actor_id
      );

      perform partner._insert_person_profile(
        p_tenant_id,
        v_contact_person_id,
        p_organization_primary_contact
      );

      insert into partner.organization_contacts (
        organization_partner_id,
        person_partner_id,
        tenant_id,
        contact_role,
        is_primary,
        created_by,
        updated_by
      )
      values (
        v_partner_id,
        v_contact_person_id,
        p_tenant_id,
        null,
        true,
        p_actor_id,
        p_actor_id
      );

      perform partner._log_partner_action(
        p_tenant_id,
        v_contact_person_id,
        'create',
        p_actor_id,
        null,
        '{}'::jsonb,
        partner._partner_snapshot(v_contact_person_id)
      );
    end if;
  end if;

  perform partner._upsert_roles(p_tenant_id, v_partner_id, v_roles);

  perform partner._log_partner_action(
    p_tenant_id,
    v_partner_id,
    'create',
    p_actor_id,
    null,
    '{}'::jsonb,
    partner._partner_snapshot(v_partner_id)
  );

  return query select v_partner_id, v_warnings;
end;
$$;

